 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let position = 0;
+
+  while (position < template.length) {
+    const open = template.indexOf("{{", position);
+    if (open === -1) {
+      tokens.push({ kind: "text", text: template.slice(position) });
+      break;
+    }
+    if (open > position) tokens.push({ kind: "text", text: template.slice(position, open) });
+
+    const raw = template.startsWith("{{{", open);
+    const opener = raw ? "{{{" : "{{";
+    const closer = raw ? "}}}" : "}}";
+    const close = template.indexOf(closer, open + opener.length);
+    if (close === -1) throw new Error("unterminated tag");
+
+    tokens.push(tagToken(template.slice(open + opener.length, close).trim(), raw));
+    position = close + closer.length;
+  }
+
+  return tokens;
 }
+
+function tagToken(content: string, raw: boolean): Token {
+  if (raw) return { kind: "value", expr: content, raw: true };
+  if (content === "else") return { kind: "else" };
+  if (content === "/if") return { kind: "end" };
+  const conditional = /^#if\b(.*)$/s.exec(content);
+  if (conditional) return { kind: "if", path: conditional[1].trim() };
+  return { kind: "value", expr: content, raw: false };
+}
